// Case generation and recording for RefDumpCollision.
//
// One "family" = one Collision method (or overload). For each family Count (>= 20000) inputs are generated by the seeded
// generator below (System.Random(GenSeed); inputs are stored, so the Rust test does not need to regenerate them), the real
// method is called by reflection and one record is written to <family>.bin:
//
//   file    : "CLSN" | u32 version = 1 | records...
//   record  : u8 threw | u32 nIn | u32 nOut | nIn x u32 | nOut x u32      (little endian; nOut = 0 when threw = 1)
//   words   : bool / int / short / ushort / byte / enum -> the value as i32 in a u32; float -> its IEEE bits;
//             struct (Vector2 X,Y; Vector4 X,Y,Z,W; Point X,Y; Rectangle X,Y,Width,Height; HurtTile type,x,y;
//             TileContact Side,Overlap,X,Y,Slope,Type) -> its public fields in declaration order;
//             array / List -> element count, then the elements.
//   inputs  : seed (case index; also the seed of Main.rand = new UnifiedRandom(seed) set before the call, of the
//             tile-type masks and of the TileActionAttempt used by CanHitWithCheck) | family specific extra words |
//             the arguments in parameter order (out parameters and arguments marked "skip" are not stored)
//   outputs : return value | ref / out parameters after the call (and the arguments marked "also") | family specific extra
//             words | the 8 static flags of Collision packed into one word, bit 0..7 = up, down, stair, stairFall, honey, shimmer, sloping, landMine
//   Before every call all 8 flags are set to false, Main.getGoodWorld / Main.dontStarveWorld to false (a family may set them),
//   Main.netMode = 0. A call that throws (IndexOutOfRangeException outside the tile array, DistFromSeg's Exception) is
//   recorded with threw = 1.
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;

static partial class RefDumpCollision
{
    const int GenSeed = 20261011;
    static Random R = new Random(GenSeed);
    const int DefaultCount = 20000;
    static readonly bool Trace = Environment.GetEnvironmentVariable("REFDUMP_COLLISION_TRACE") == "1";

    static Type V2T, V4T, PtT, RectT;
    static ConstructorInfo V2C, V4C, PtC, RectC;

    static object V2(double x, double y) { return V2C.Invoke(new object[] { (float)x, (float)y }); }
    static object V2f(float x, float y) { return V2C.Invoke(new object[] { x, y }); }
    static object Pt(int x, int y) { return PtC.Invoke(new object[] { x, y }); }
    static object Rect(int x, int y, int w, int h) { return RectC.Invoke(new object[] { x, y, w, h }); }
    static float V2X(object v) { return (float)V2T.GetField("X").GetValue(v); }
    static float V2Y(object v) { return (float)V2T.GetField("Y").GetValue(v); }

    class Case
    {
        public object[] Args;
        public List<uint> Extra = new List<uint>();
        public Action Pre;
        public Func<object[], List<uint>> After;
    }

    class Fam
    {
        public string Name, Method, Sig;
        public int Count = DefaultCount;
        public Func<Case> Gen;
        public HashSet<int> SkipIn = new HashSet<int>();
        public HashSet<int> Also = new HashSet<int>();
        public Func<object[], bool> Prescreen;   // false = the real method would loop for ever on these arguments: the case is left out
    }

    // ---------------------------------------------------------------- encoding
    static uint FBits(float f) { return BitConverter.ToUInt32(BitConverter.GetBytes(f), 0); }
    static void Emit(object v, List<uint> w)
    {
        if (v == null) { w.Add(0xFFFFFFFFu); return; }
        Type t = v.GetType();
        if (t == typeof(bool)) w.Add((bool)v ? 1u : 0u);
        else if (t == typeof(float)) w.Add(FBits((float)v));
        else if (t == typeof(int)) w.Add((uint)(int)v);
        else if (t == typeof(uint)) w.Add((uint)v);
        else if (t == typeof(short)) w.Add((uint)(int)(short)v);
        else if (t == typeof(ushort)) w.Add((uint)(ushort)v);
        else if (t == typeof(byte)) w.Add((uint)(byte)v);
        else if (t.IsEnum) w.Add((uint)Convert.ToInt32(v));
        else if (t == typeof(double)) { long b = BitConverter.DoubleToInt64Bits((double)v); w.Add((uint)b); w.Add((uint)(b >> 32)); }
        else if (v is IList) { IList l = (IList)v; w.Add((uint)l.Count); foreach (object o in l) Emit(o, w); }
        else foreach (FieldInfo f in t.GetFields(BindingFlags.Public | BindingFlags.Instance)) Emit(f.GetValue(v), w);
    }
    static void EmitF(List<uint> w, float f) { w.Add(FBits(f)); }
    static void EmitI(List<uint> w, int i) { w.Add((uint)i); }

    // ---------------------------------------------------------------- generators of interesting inputs
    static readonly int[,] Sizes = { { 20, 42 }, { 20, 42 }, { 20, 42 }, { 16, 16 }, { 16, 16 }, { 10, 10 }, { 40, 40 }, { 8, 8 }, { 14, 28 }, { 12, 12 }, { 32, 32 }, { 6, 6 } };
    static void Size(out int w, out int h)
    {
        if (R.Next(10) == 0) { w = R.Next(1, 65); h = R.Next(1, 65); return; }
        int k = R.Next(Sizes.GetLength(0));
        w = Sizes[k, 0]; h = Sizes[k, 1];
    }
    static readonly float[] Jitters = { 0f, 0f, 0f, 0.0001f, -0.0001f, 0.01f, -0.01f, 0.5f, -0.5f, 1f, -1f, 0.001f, 0.25f, -0.25f };
    static float Jit() { return Jitters[R.Next(Jitters.Length)]; }
    static double Uni(double lo, double hi) { return lo + R.NextDouble() * (hi - lo); }

    // an anchor tile (x, y) near something interesting; may be outside the world (edge cases)
    static int[] Anchor()
    {
        int m = R.Next(100);
        int kind;
        if (m < 22) kind = 9;
        else if (m < 30)
        {
            int side = R.Next(4);
            int x = R.Next(W), y = R.Next(H);
            if (side == 0) x = R.Next(-3, 5);
            else if (side == 1) x = R.Next(W - 6, W + 3);
            else if (side == 2) y = R.Next(-3, 5);
            else y = R.Next(H - 46, H + 3);
            return new int[] { x, y };
        }
        else if (m < 38) kind = 0;
        else if (m < 47) kind = 1;
        else if (m < 51) kind = 2;
        else if (m < 56) kind = 3;
        else if (m < 64) kind = 4;
        else if (m < 68) kind = 5;
        else if (m < 78) kind = 6;
        else if (m < 84) kind = 7;
        else if (m < 88) kind = 8;
        else kind = 10;
        List<int> l = Spots[kind];
        int e = l[R.Next(l.Count)];
        return new int[] { e / H, e % H };
    }
    static int[] StampAnchor() { return new int[] { StampX + R.Next(SW), StampY + R.Next(SH) }; }

    static float OffAxis(int dim)
    {
        int m = R.Next(100);
        if (m < 30) return (float)Uni(-40, 40);
        if (m < 62)
        {
            float[] bases = { 0, -dim, 16, 16 - dim, 8, 8 - dim, -dim / 2f, 4, 12 - dim, 15, -dim + 1 };
            return bases[R.Next(bases.Length)] + Jit();
        }
        if (m < 82) return R.Next(-30, 31);
        return (float)Uni(-4, 4);
    }

    // position (float x, y) of an entity of size w x h near the anchor
    static void PosNear(int[] a, int w, int h, out float px, out float py)
    {
        int tx = a[0] + (R.Next(4) == 0 ? R.Next(-2, 3) : 0), ty = a[1] + (R.Next(4) == 0 ? R.Next(-2, 3) : 0);
        px = (float)(tx * 16.0 + OffAxis(w));
        py = (float)(ty * 16.0 + OffAxis(h));
    }
    static object PosObj(int[] a, int w, int h) { float x, y; PosNear(a, w, h, out x, out y); return V2f(x, y); }

    static readonly float[] StepVals = { 0.5f, 1f, 2f, 4f, 8f, 16f, 3f, 5f, 6.5f, 10f, 12f, 20f, 32f };
    static void Vel(out float vx, out float vy)
    {
        int m = R.Next(100);
        if (m < 8) { vx = 0; vy = 0; }
        else if (m < 22) { vx = (float)Uni(-0.5, 0.5); vy = (float)Uni(-0.5, 0.5); }
        else if (m < 52) { vx = (float)Uni(-20, 20); vy = (float)Uni(-20, 20); }
        else if (m < 66) { vx = R.Next(-20, 21); vy = R.Next(-20, 21); }
        else if (m < 80) { vx = (float)Uni(-4, 4); vy = (float)Uni(0.1, 12); if (R.Next(3) == 0) vy = 0.3f; }
        else
        {
            vx = StepVals[R.Next(StepVals.Length)] * (R.Next(2) == 0 ? 1 : -1) * (R.Next(3) == 0 ? 0 : 1);
            vy = StepVals[R.Next(StepVals.Length)] * (R.Next(2) == 0 ? 1 : -1) * (R.Next(3) == 0 ? 0 : 1);
        }
    }
    static object VelObj() { float x, y; Vel(out x, out y); return V2f(x, y); }
    static bool Flip(int percent) { return R.Next(100) < percent; }
    static bool B() { return R.Next(2) == 0; }

    // tile coordinates near an anchor
    static int[] TileNear(int[] a, int spread)
    {
        return new int[] { a[0] + R.Next(-spread, spread + 1), a[1] + R.Next(-spread, spread + 1) };
    }

    // ---------------------------------------------------------------- reflection helpers
    static MethodInfo FindM(string name, string sig)
    {
        string[] tokens = sig.Length == 0 ? new string[0] : sig.Split(',');
        foreach (MethodInfo m in CollisionT.GetMethods(AllStatic))
        {
            if (m.Name != name) continue;
            ParameterInfo[] ps = m.GetParameters();
            if (ps.Length != tokens.Length) continue;
            bool ok = true;
            for (int i = 0; i < ps.Length; i++) if (ps[i].ParameterType.Name != tokens[i]) { ok = false; break; }
            if (ok) return m;
        }
        throw new Exception("Collision." + name + "(" + sig + ") not found");
    }

    static FieldInfo[] StaticF;
    static readonly string[] StaticNames = { "up", "down", "stair", "stairFall", "honey", "shimmer", "sloping", "landMine" };

    // masks and checks derived from the seed (the Rust test computes the same)
    static uint CurSeed;
    static int CheckCalls;
    public static bool CheckImpl(int x, int y)
    {
        CheckCalls++;
        return (unchecked((uint)(x * 73856093) ^ (uint)(y * 19349663) ^ CurSeed) & 7u) != 0u;
    }
    static bool[] Mask(uint seed, int len)
    {
        bool[] a = new bool[len];
        for (int t = 0; t < len; t++) a[t] = ((unchecked((uint)t * 2654435761u) ^ unchecked(seed * 40503u)) >> 11 & 3u) == 0u;
        return a;
    }

    static object MakeEntity(string typeName, float x, float y, int w, int h)
    {
        object e = Activator.CreateInstance(T(typeName));
        T("Terraria.Entity").GetField("position").SetValue(e, V2f(x, y));
        T("Terraria.Entity").GetField("width").SetValue(e, w);
        T("Terraria.Entity").GetField("height").SetValue(e, h);
        return e;
    }

    static List<Fam> Families = new List<Fam>();
    static void Add(string name, string method, string sig, Func<Case> gen, string skipIn = "", string also = "", int count = DefaultCount)
    {
        var f = new Fam { Name = name, Method = method, Sig = sig, Gen = gen, Count = count };
        foreach (string s in skipIn.Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries)) f.SkipIn.Add(int.Parse(s));
        foreach (string s in also.Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries)) f.Also.Add(int.Parse(s));
        Families.Add(f);
    }

    static Case C(params object[] args) { return new Case { Args = args }; }

    // ---------------------------------------------------------------- the families
    static void DefineFamilies()
    {
        V2T = CollisionT.GetMethod("CheckAABBvAABBCollision").GetParameters()[0].ParameterType;
        V4T = CollisionT.GetMethod("WalkDownSlope").ReturnType;
        PtT = CollisionT.GetMethod("HitLineWall").ReturnType;
        RectT = CollisionT.GetMethod("TryChangingSizeFromBottomCenter").GetParameters()[0].ParameterType;
        V2C = V2T.GetConstructor(new Type[] { typeof(float), typeof(float) });
        V4C = V4T.GetConstructor(new Type[] { typeof(float), typeof(float), typeof(float), typeof(float) });
        PtC = PtT.GetConstructor(new Type[] { typeof(int), typeof(int) });
        RectC = RectT.GetConstructor(new Type[] { typeof(int), typeof(int), typeof(int), typeof(int) });
        StaticF = StaticNames.Select(n => CollisionT.GetField(n, AllStatic)).ToArray();
        Type tileAction = T("Terraria.Utils+TileActionAttempt");

        // ---- pure geometry ---------------------------------------------------------------------------------
        Func<object[]> geo4 = () =>
        {
            // two segments / a box and a segment, in a 60 x 60 area; many degenerate (equal, collinear, axis aligned) cases
            double s = R.Next(3) == 0 ? 1 : (R.Next(2) == 0 ? 10 : 60);
            Func<double> c = () => (R.Next(3) == 0) ? Math.Round(Uni(-s, s)) : Uni(-s, s);
            double ax = c(), ay = c(), bx = c(), by = c(), cx = c(), cy = c(), dx = c(), dy = c();
            int m = R.Next(100);
            if (m < 8) { bx = ax; by = ay; }                              // a1 == a2
            else if (m < 16) { dx = cx; dy = cy; }                        // b1 == b2
            else if (m < 22) { cx = ax; cy = ay; }                        // shared start
            else if (m < 34)
            {                                                             // collinear
                double t1 = Uni(-1, 2), t2 = Uni(-1, 2);
                cx = ax + t1 * (bx - ax); cy = ay + t1 * (by - ay); dx = ax + t2 * (bx - ax); dy = ay + t2 * (by - ay);
            }
            else if (m < 42) { by = ay; dy = cy; }                        // both horizontal
            else if (m < 50) { bx = ax; dx = cx; }                        // both vertical
            else if (m < 58) { dx = cx + (bx - ax); dy = cy + (by - ay); } // parallel
            return new object[] { V2(ax, ay), V2(bx, by), V2(cx, cy), V2(dx, dy) };
        };
        Add("CheckLinevLine", "CheckLinevLine", "Vector2,Vector2,Vector2,Vector2", () => { var c = new Case(); c.Args = geo4(); return c; });
        Func<object[]> aabb2 = () =>
        {
            double s = R.Next(3) == 0 ? 2 : 40;
            Func<double> c = () => (R.Next(3) == 0) ? Math.Round(Uni(-s, s)) : Uni(-s, s);
            double w1 = R.Next(10) == 0 ? 0 : Uni(0, 30), h1 = R.Next(10) == 0 ? 0 : Uni(0, 30);
            double w2 = R.Next(10) == 0 ? 0 : Uni(0, 30), h2 = R.Next(10) == 0 ? 0 : Uni(0, 30);
            if (R.Next(4) == 0) { w1 = Math.Round(w1); h1 = Math.Round(h1); w2 = Math.Round(w2); h2 = Math.Round(h2); }
            return new object[] { V2(c(), c()), V2(w1, h1), V2(c(), c()), V2(w2, h2) };
        };
        Add("CheckAABBvAABBCollision", "CheckAABBvAABBCollision", "Vector2,Vector2,Vector2,Vector2", () => { var c = new Case(); c.Args = aabb2(); return c; });
        Func<object[]> aabbLine = () =>
        {
            double s = R.Next(3) == 0 ? 3 : 40;
            Func<double> c = () => (R.Next(3) == 0) ? Math.Round(Uni(-s, s)) : Uni(-s, s);
            double w = R.Next(12) == 0 ? 0 : Uni(0.5, 30), h = R.Next(12) == 0 ? 0 : Uni(0.5, 30);
            if (R.Next(4) == 0) { w = Math.Round(w); h = Math.Round(h); }
            double px = c(), py = c(), sx = c(), sy = c(), ex = c(), ey = c();
            int m = R.Next(100);
            if (m < 8) { ex = sx; }
            else if (m < 16) { ey = sy; }
            else if (m < 20) { ex = sx; ey = sy; }
            return new object[] { V2(px, py), V2(w, h), V2(sx, sy), V2(ex, ey) };
        };
        Add("CheckAABBvLineCollision4", "CheckAABBvLineCollision", "Vector2,Vector2,Vector2,Vector2", () => { var c = new Case(); c.Args = aabbLine(); return c; });
        Families[Families.Count - 1].Prescreen = AabbLineTerminates;   // the replica decides; a thread guard (Guard = true) is too timing sensitive on a loaded machine
        Add("CheckAABBvLineCollision2", "CheckAABBvLineCollision2", "Vector2,Vector2,Vector2,Vector2", () => { var c = new Case(); c.Args = aabbLine(); return c; });
        Add("CheckAABBvLineCollision6", "CheckAABBvLineCollision", "Vector2,Vector2,Vector2,Vector2,Single,Single&", () =>
        {
            var a = aabbLine();
            double[] lw = { 0.0001, 0.5, 1, 2, 4, 8, 16 };
            return C(a[0], a[1], a[2], a[3], (float)(R.Next(3) == 0 ? lw[R.Next(lw.Length)] : Uni(0.01, 12)), 123.5f);
        });

        // ---- lines of sight --------------------------------------------------------------------------------
        Func<int[]> anchorForLine = () => R.Next(3) == 0 ? StampAnchor() : Anchor();
        Func<Case> los = () =>
        {
            int[] a = anchorForLine();
            int[] b = R.Next(6) == 0 ? Anchor() : TileNear(a, R.Next(2) == 0 ? 8 : 40);
            int w1, h1, w2, h2; Size(out w1, out h1); Size(out w2, out h2);
            float x1, y1, x2, y2; PosNear(a, w1, h1, out x1, out y1); PosNear(b, w2, h2, out x2, out y2);
            return C(V2f(x1, y1), w1, h1, V2f(x2, y2), w2, h2);
        };
        Add("CanHit_Vector2", "CanHit", "Vector2,Int32,Int32,Vector2,Int32,Int32", los);
        Add("CanHit_Point", "CanHit", "Point,Int32,Int32,Point,Int32,Int32", () =>
        {
            Case c = los();
            c.Args = new object[] { Pt((int)V2X(c.Args[0]), (int)V2Y(c.Args[0])), c.Args[1], c.Args[2], Pt((int)V2X(c.Args[3]), (int)V2Y(c.Args[3])), c.Args[4], c.Args[5] };
            return c;
        });
        Add("CanHitLine", "CanHitLine", "Vector2,Int32,Int32,Vector2,Int32,Int32", los);
        Add("CanHitWithCheck", "CanHitWithCheck", "Vector2,Int32,Int32,Vector2,Int32,Int32,TileActionAttempt", () =>
        {
            Case c = los();
            uint seed = (uint)R.Next();
            c.Args = new object[] { c.Args[0], c.Args[1], c.Args[2], c.Args[3], c.Args[4], c.Args[5], Delegate.CreateDelegate(tileAction, typeof(RefDumpCollision).GetMethod("CheckImpl")) };
            c.Extra.Add(seed);
            c.Pre = () => { CurSeed = seed; CheckCalls = 0; };
            c.After = args => { var w = new List<uint>(); w.Add((uint)CheckCalls); return w; };
            return c;
        }, "6");
        Add("HitLine", "HitLine", "Int32,Int32,Int32,Int32,Int32,Int32,List`1,Point&", () =>
        {
            int[] a = anchorForLine();
            int[] b = R.Next(6) == 0 ? Anchor() : TileNear(a, R.Next(2) == 0 ? 8 : 40);
            var list = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(PtT));
            int n = R.Next(4) == 0 ? R.Next(1, 4) : 0;
            for (int i = 0; i < n; i++)
            {
                int[] ig = R.Next(2) == 0 ? new int[] { a[0], a[1] } : TileNear(a, 3);
                list.Add(Pt(ig[0] + (R.Next(3) - 1), ig[1] + (R.Next(3) - 1)));
            }
            return C(a[0], a[1], b[0], b[1], R.Next(3) - 1, R.Next(3) - 1, list, null);
        });
        Add("AnyWallOfTypeOnLine", "AnyWallOfTypeOnLine", "Int32,Int32,Int32,Int32,UInt16", () =>
        {
            int[] a = anchorForLine();
            int[] b = TileNear(a, R.Next(2) == 0 ? 8 : 30);
            ushort wall = (ushort)(R.Next(3) == 0 ? R.Next(0, 5) : R.Next(0, 3));
            return C(a[0], a[1], b[0], b[1], wall);
        });
        Add("HitLineWall", "HitLineWall", "Int32,Int32,Int32,Int32", () =>
        {
            int[] a = anchorForLine();
            int[] b = TileNear(a, R.Next(2) == 0 ? 8 : 30);
            return C(a[0], a[1], b[0], b[1]);
        });
        Add("HitSpecificWallSubstep", "HitSpecificWallSubstep", "Int32,Int32,UInt16", () =>
        {
            int[] a = Anchor();
            return C(a[0], a[1], (ushort)R.Next(0, 4));
        });
        Add("HitWallSubstep", "HitWallSubstep", "Int32,Int32", () => { int[] a = Anchor(); return C(a[0], a[1]); });
        Add("EmptyTile", "EmptyTile", "Int32,Int32,Boolean", () => { int[] a = Anchor(); return C(a[0], a[1], Flip(30)); });

        // ---- liquids and points ----------------------------------------------------------------------------
        Add("DrownCollision", "DrownCollision", "Vector2,Int32,Int32,Single,Boolean", () =>
        {
            int w, h; Size(out w, out h);
            return C(PosObj(Anchor(), w, h), w, h, R.Next(3) == 0 ? 1f : (R.Next(2) == 0 ? -1f : (float)Uni(-2, 2)), Flip(40));
        });
        Add("IsWorldPointSolid", "IsWorldPointSolid", "Vector2,Boolean", () =>
        {
            int[] a = Anchor();
            float x, y; PosNear(a, 0, 0, out x, out y);
            if (R.Next(4) == 0) { x = a[0] * 16 + R.Next(0, 17); y = a[1] * 16 + R.Next(0, 17); }
            return C(V2f(x, y), Flip(40));
        });
        Add("GetWaterLine_Point", "GetWaterLine", "Point,Single&", () => { int[] a = Anchor(); return C(Pt(a[0], a[1]), 0f); });
        Add("GetWaterLine_Ints", "GetWaterLine", "Int32,Int32,Single&", () => { int[] a = Anchor(); return C(a[0], a[1], 0f); });
        Add("GetWaterLineIterate_Point", "GetWaterLineIterate", "Point,Single&", () => { int[] a = Anchor(); return C(Pt(a[0], a[1]), 0f); });
        Add("GetWaterLineIterate_Ints", "GetWaterLineIterate", "Int32,Int32,Single&", () => { int[] a = Anchor(); return C(a[0], a[1], 0f); });
        Add("WetCollision", "WetCollision", "Vector2,Int32,Int32", () => { int w, h; Size(out w, out h); return C(PosObj(Anchor(), w, h), w, h); });
        Add("LavaCollision", "LavaCollision", "Vector2,Int32,Int32", () => { int w, h; Size(out w, out h); return C(PosObj(Anchor(), w, h), w, h); });

        // ---- slopes ----------------------------------------------------------------------------------------
        Add("WalkDownSlope", "WalkDownSlope", "Vector2,Vector2,Int32,Int32,Single", () =>
        {
            int w, h; Size(out w, out h);
            float vx, vy; Vel(out vx, out vy);
            float gravity = R.Next(3) == 0 ? 0f : (R.Next(2) == 0 ? 0.3f : (float)Uni(0, 1));
            if (R.Next(10) < 7) vy = gravity;
            return C(PosObj(Anchor(), w, h), V2f(vx, vy), w, h, gravity);
        });
        Add("SlopeCollision", "SlopeCollision", "Vector2,Vector2,Int32,Int32,Single,Boolean,Boolean", () =>
        {
            int w, h; Size(out w, out h);
            return C(PosObj(Anchor(), w, h), VelObj(), w, h, R.Next(3) == 0 ? 0f : (float)Uni(-1, 2), Flip(30), Flip(15));
        });
        Add("noSlopeCollision", "noSlopeCollision", "Vector2,Vector2,Int32,Int32,Boolean,Boolean", () =>
        {
            int w, h; Size(out w, out h);
            return C(PosObj(Anchor(), w, h), VelObj(), w, h, Flip(35), Flip(25));
        });
        Add("BuildTileContacts", "BuildTileContacts", "Vector2,Int32,Int32,List`1", () =>
        {
            int w, h; Size(out w, out h);
            object pos = PosObj(Anchor(), w, h);
