    // ---------------------------------------------------------------- running
    static byte[] WordBytes(List<uint> w)
    {
        byte[] b = new byte[w.Count * 4];
        for (int i = 0; i < w.Count; i++) { b[i * 4] = (byte)w[i]; b[i * 4 + 1] = (byte)(w[i] >> 8); b[i * 4 + 2] = (byte)(w[i] >> 16); b[i * 4 + 3] = (byte)(w[i] >> 24); }
        return b;
    }

    static byte[] SaveRegion(int x0, int y0, int x1, int y1)
    {
        byte[] buf = new byte[(x1 - x0 + 1) * (y1 - y0 + 1) * RecordSize];
        int o = 0;
        for (int x = x0; x <= x1; x++) for (int y = y0; y <= y1; y++) { ReadTile(x, y, buf, o); o += RecordSize; }
        return buf;
    }
    static void RestoreRegion(int x0, int y0, int x1, int y1, byte[] buf)
    {
        int o = 0;
        byte[] rec = new byte[RecordSize];
        for (int x = x0; x <= x1; x++) for (int y = y0; y <= y1; y++) { Array.Copy(buf, o, rec, 0, RecordSize); SetTileFields(x, y, rec); o += RecordSize; }
    }

    // GetWaterLineIterate does `if (Main.tile[X, Y] == null) Main.tile[X, Y] = new Tile();` for a Y that can be outside the world: that
    // allocation would stay in the game for the later cases (a null slot becomes an empty tile). Put the slots back to null.
    static void ForgetAllocatedTiles(object[] args)
    {
        int x, y;
        if (args[0] is int) { x = (int)args[0]; y = (int)args[1]; }
        else { x = (int)PtT.GetField("X").GetValue(args[0]); y = (int)PtT.GetField("Y").GetValue(args[0]); }
        int l0 = TileArr.GetLength(0), l1 = TileArr.GetLength(1);
        if (x < 0 || x >= l0) return;
        if (x < W) { for (int yy = H; yy < H + 3 && yy < l1; yy++) TileArr.SetValue(null, x, yy); }
        else if (y + 1 >= 0 && y + 1 < l1) TileArr.SetValue(null, x, y + 1);
    }

    // writes back the tiles of the region that differ from the saved copy (SwitchTiles may explode a land mine)
    static void RestoreChanged(int x0, int y0, int x1, int y1, byte[] buf)
    {
        int o = 0;
        byte[] rec = new byte[RecordSize], cur = new byte[RecordSize];
        for (int x = x0; x <= x1; x++)
            for (int y = y0; y <= y1; y++)
            {
                ReadTile(x, y, cur, 0);
                Array.Copy(buf, o, rec, 0, RecordSize);
                bool same = true;
                for (int k = 0; k < RecordSize; k++) if (cur[k] != rec[k]) { same = false; break; }
                if (!same) SetTileFields(x, y, rec);
                o += RecordSize;
            }
    }

    // Replica of the loop of Collision.CheckAABBvLineCollision(4 arguments) (same source, same expression shapes, struct fields for the
    // line start) with an iteration limit: the real loop does not end for some inputs (the clipped point lands just outside the box again,
    // forever) and cannot be aborted. Such inputs are left out of the cases (counted in collision.json).
    struct P2 { public float X, Y; }
    static int Outcode(P2 box, P2 dim, P2 point)
    {
        float num = box.X + dim.X;
        float num2 = box.Y + dim.Y;
        int num3 = 0;
        if (dim.X <= 0f) num3 |= 5;
        else if (point.X < box.X) num3 |= 1;
        else if (point.X - num > 0f) num3 |= 4;
        if (dim.Y <= 0f) num3 |= 0xA;
        else if (point.Y < box.Y) num3 |= 2;
        else if (point.Y - num2 > 0f) num3 |= 8;
        return num3;
    }
    static bool AabbLineTerminates(object[] a)
    {
        P2 box = new P2 { X = V2X(a[0]), Y = V2Y(a[0]) }, dim = new P2 { X = V2X(a[1]), Y = V2Y(a[1]) };
        P2 lineStart = new P2 { X = V2X(a[2]), Y = V2Y(a[2]) }, lineEnd = new P2 { X = V2X(a[3]), Y = V2Y(a[3]) };
        if (Outcode(box, dim, lineEnd) == 0) return true;
        int num = Outcode(box, dim, lineEnd);
        for (int it = 0; it < 2000; it++)
        {
            int num2 = Outcode(box, dim, lineStart);
            if (num2 == 0) return true;
            if ((num2 & num) != 0) return true;
            if ((num2 & 5) != 0)
            {
                float num3 = box.X;
                if ((num2 & 4) != 0) num3 += dim.X;
                lineStart.Y += (num3 - lineStart.X) * (lineEnd.Y - lineStart.Y) / (lineEnd.X - lineStart.X);
                lineStart.X = num3;
            }
            else
            {
                float num4 = box.Y;
                if ((num2 & 8) != 0) num4 += dim.Y;
                lineStart.X += (num4 - lineStart.Y) * (lineEnd.X - lineStart.X) / (lineEnd.Y - lineStart.Y);
                lineStart.Y = num4;
            }
        }
        return false;
    }

    // What does this JIT do with float arithmetic? On x86 the legacy JIT computes with the x87 unit and keeps float locals / temporaries in
    // registers without rounding them to 32 bits, so  float x = a + b; return x - a;  gives 1 for a = 2^24, b = 1 (SSE single precision gives 0).
    [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
    static float ProbeLocal(float a, float b) { float x = a + b; return x - a; }
    [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
    static float ProbeExpr(float a, float b) { return a + b - a; }
    [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
    static void ProbeField(float a, float b, ref float dst) { dst = a + b; }

    static string FamilySummary(Fam f, int count, int threw, int distinctOut, int hangs, int trues)
    {
        return "{\"family\":" + Q(f.Name) + ",\"method\":" + Q("Collision." + f.Method + "(" + f.Sig + ")") + ",\"cases\":" + count + ",\"threw\":" + threw + ",\"distinctOutputs\":" + distinctOut + ",\"inputsSkippedBecauseTheGameLoopsForever\":" + hangs + ",\"returnedTrue\":" + (FindM(f.Method, f.Sig).ReturnType == typeof(bool) ? trues.ToString() : "null") + "}";
    }

    static void RunAllFamilies(string srcSha)
    {
        DefineFamilies();
        Type ur = T("Terraria.Utilities.UnifiedRandom");
        var summaries = new List<string>();
        var sw = System.Diagnostics.Stopwatch.StartNew();
        string only = Environment.GetEnvironmentVariable("REFDUMP_COLLISION_ONLY");
        string countOverride = Environment.GetEnvironmentVariable("REFDUMP_COLLISION_COUNT");
        foreach (Fam f in Families)
        {
            if (only != null && only.Length > 0 && !(";" + only + ";").Contains(";" + f.Name + ";")) continue;
            MethodInfo m = FindM(f.Method, f.Sig);
            ParameterInfo[] ps = m.GetParameters();
            int count = countOverride != null ? int.Parse(countOverride) : f.Count;
            int threw = 0, hangs = 0, trues = 0;
            var distinct = new HashSet<string>();
            string path = Path.Combine(OutDir, f.Name + ".bin");
            using (var fs = new BufferedStream(new FileStream(path, FileMode.Create), 1 << 20))
            {
                fs.Write(new byte[] { (byte)'C', (byte)'L', (byte)'S', (byte)'N', 1, 0, 0, 0 }, 0, 8);
                for (int i = 0; i < count; i++)
                {
                    Case c = f.Gen();
                    if (f.Prescreen != null && !f.Prescreen(c.Args)) { hangs++; i--; continue; }
                    uint seed = (uint)i;
                    var inW = new List<uint>();
                    inW.Add(seed);
                    inW.AddRange(c.Extra);
                    for (int k = 0; k < ps.Length; k++)
                    {
                        if (f.SkipIn.Contains(k) || ps[k].IsOut) continue;
                        Emit(c.Args[k], inW);
                    }
                    // state before the call
                    foreach (FieldInfo sf in StaticF) sf.SetValue(null, false);
                    SSet(MainT, "getGoodWorld", false); SSet(MainT, "dontStarveWorld", false); SSet(MainT, "netMode", 0);
                    SSet(MainT, "rand", Activator.CreateInstance(ur, new object[] { (int)seed }));
                    CurSeed = seed;
                    if (c.Pre != null) c.Pre();
                    byte[] saved = null; int rx0 = 0, ry0 = 0, rx1 = -1, ry1 = -1;
                    if (f.Name == "SwitchTiles")
                    {
                        int tx = (int)c.Extra[0], ty = (int)c.Extra[1];
                        rx0 = Math.Max(0, tx - 6); ry0 = Math.Max(0, ty - 6); rx1 = Math.Min(W - 1, tx + 6); ry1 = Math.Min(H - 1, ty + 6);
                        saved = SaveRegion(rx0, ry0, rx1, ry1);
                    }
                    var outW = new List<uint>();
                    bool didThrow = false;
                    object ret = null;
                    if (Trace) { Console.WriteLine(f.Name + " #" + i + " " + string.Join(",", inW.Select(x => x.ToString()).ToArray())); Console.Out.Flush(); }
                    try { ret = m.Invoke(null, c.Args); }
                    catch (TargetInvocationException) { didThrow = true; }
                    if (saved != null) RestoreChanged(rx0, ry0, rx1, ry1, saved);
                    if (f.Name.StartsWith("GetWaterLineIterate")) ForgetAllocatedTiles(c.Args);
                    if (didThrow) threw++;
                    else
                    {
                        if (m.ReturnType != typeof(void)) Emit(ret, outW);
                        if (ret is bool && (bool)ret) trues++;
                        for (int k = 0; k < ps.Length; k++)
                            if (ps[k].ParameterType.IsByRef || f.Also.Contains(k)) Emit(c.Args[k], outW);
                        if (c.After != null) outW.AddRange(c.After(c.Args));
                        uint flagBits = 0;
                        for (int fb = 0; fb < StaticF.Length; fb++) if ((bool)StaticF[fb].GetValue(null)) flagBits |= 1u << fb;
                        outW.Add(flagBits);
                        if (distinct.Count < 100000) distinct.Add(string.Join(",", outW.Select(x => x.ToString()).ToArray()));
                    }
                    fs.WriteByte(didThrow ? (byte)1 : (byte)0);
                    fs.Write(BitConverter.GetBytes((uint)inW.Count), 0, 4);
                    fs.Write(BitConverter.GetBytes((uint)outW.Count), 0, 4);
                    byte[] ib = WordBytes(inW); fs.Write(ib, 0, ib.Length);
                    byte[] ob = WordBytes(outW); fs.Write(ob, 0, ob.Length);
                }
            }
            summaries.Add(FamilySummary(f, count, threw, distinct.Count, hangs, trues));
            Console.WriteLine(f.Name + ": " + count + " cases, " + threw + " threw, " + distinct.Count + " distinct outputs, true=" + trues + "  (" + sw.ElapsedMilliseconds + " ms)");
        }
        var json = new StringBuilder("{\n");
        json.Append("\"generator\":\"tools/refdump_collision/RefDumpCollision.cs\",\n");
        json.Append("\"world\":\"ref_small.wld\",\"worldSha256\":" + Q(srcSha) + ",\"width\":" + W + ",\"height\":" + H + ",\n");
        float stored = 0f; ProbeField(16777216f, 1f, ref stored);
        json.Append("\"fpProbe\":{\"what\":\"legacy x86 JIT: float locals and temporaries are not rounded to 32 bits\",\"x=a+b;x-a (a=2^24,b=1; SSE gives 0)\":" + ProbeLocal(16777216f, 1f).ToString(Inv) + ",\"a+b-a\":" + ProbeExpr(16777216f, 1f).ToString(Inv) + ",\"stored a+b\":" + stored.ToString(Inv) + "},\n");
        json.Append("\"tileArray\":[" + TileArr.GetLength(0) + "," + TileArr.GetLength(1) + "],\n");
        json.Append("\"genSeed\":" + GenSeed + ",\"stampSeed\":" + StampSeed + ",\"stampBlock\":{\"x\":" + StampX + ",\"y\":" + StampY + ",\"w\":" + SW + ",\"h\":" + SH + ",\"tiles\":" + stampList.Count + "},\n");
        json.Append("\"flags\":{\"Main.netMode\":0,\"Collision.statics\":\"all false before every call\"},\n");
        json.Append("\"families\":[\n" + string.Join(",\n", summaries.ToArray()) + "\n]\n}\n");
        File.WriteAllBytes(Path.Combine(OutDir, "collision.json"), new UTF8Encoding(false).GetBytes(json.ToString()));
    }
}
